# -*- coding: utf-8 -*-
# HFSS (AEDT) IronPython script -- Yagi-type side launcher (driven pin + reflector post + 2 director posts) on RT/duroid 5880 3.175 mm, with a surface of OFF-state loop cells outside a keep-out. Generated by lwmom (Phase 28).
# MODEL_ONLY / NOT_HFSS_VALIDATED. AEDT calls: VERIFIED in AEDT (3x3 smoke build 2026-10-24): CreatePolyline sheets, Unite, AssignPerfectE, AssignLumpedRLC with one element type per sheet (here C only = OFF diode, 28.2 fF).
# Copied from the Phase 26 hex150 script (built the 150 mm board): substrate/ground, pin cylinder, coax lumped port, radiation box, setup, far-field sphere.
# NOT checked in AEDT: the post cylinders (same CreateCylinder call as the pin), the many-sheet Unite of the cells, the azimuth polyline.
import math
import ScriptEnv
ScriptEnv.Initialize("Ansoft.ElectronicsDesktop")
oDesktop.RestoreWindow()

def attrs(name, material, solve_inside, color="(255 128 0)", transp=0):
    return ["NAME:Attributes", "Name:=", name, "Flags:=", "", "Color:=", color, "Transparency:=", transp,
            "PartCoordinateSystem:=", "Global", "UDMId:=", "", "MaterialValue:=", '"' + material + '"',
            "SurfaceMaterialValue:=", '""', "SolveInside:=", solve_inside, "IsMaterialEditable:=", True,
            "UseMaterialAppearance:=", False, "IsLightweight:=", False]

def mm(v):
    return repr(float(v)) + "mm"

def poly_sheet(oEditor, name, pts, z, color="(255 128 0)"):
    pl = ["NAME:PolylineParameters", "IsPolylineCovered:=", True, "IsPolylineClosed:=", True,
          ["NAME:PolylinePoints"] + [["NAME:PLPoint", "X:=", mm(x), "Y:=", mm(y), "Z:=", z] for (x, y) in list(pts) + [pts[0]]],
          ["NAME:PolylineSegments"] + [["NAME:PLSegment", "SegmentType:=", "Line", "StartIndex:=", k, "NoOfPoints:=", 2] for k in range(len(pts))],
          ["NAME:PolylineXSection", "XSectionType:=", "None", "XSectionOrient:=", "Auto", "XSectionWidth:=", "0mm",
           "XSectionTopWidth:=", "0mm", "XSectionHeight:=", "0mm", "XSectionNumSegments:=", "0", "XSectionBendType:=", "Corner"]]
    oEditor.CreatePolyline(pl, attrs(name, "vacuum", True, color))

# ------------------------------------------------------------------ parameters (edit here)
LOADED_SURFACE = True        # False: bare grounded slab (run this first)
H = 3.175                    # substrate thickness [mm]
PIN_R = 0.635                # radius of the driven pin and of the posts [mm] (project pin)
# Yagi (model, results/phase28/f10/launcher/launcher_model.json): top heights are ABOVE THE SUBSTRATE SURFACE, spacings along +x (directors) / -x (reflector)
TD = 3.727                  # driven pin top
S_REFL, T_REFL = 9.031, 8.361
S_D1, T_D1 = 13.142, 5.522
S_D2, T_D2 = 13.959, 5.113
SO = 6.6; WR = 1.2; GAP = 0.6; PITCH = 9.0
C_OFF = "0.0282pF"           # OFF diode: C only (measured MA4AGP907, 0 V)
CELLS = [[0, 0.0, -90.0], [1, -9.0, -81.0], [2, 0.0, -81.0], [3, 9.0, -81.0], [4, -27.0, -72.0], [5, -18.0, -72.0], [6, -9.0, -72.0], [7, 0.0, -72.0], [8, 9.0, -72.0], [9, 18.0, -72.0], [10, 27.0, -72.0], [11, -45.0, -63.0], [12, -36.0, -63.0], [13, -27.0, -63.0], [14, -18.0, -63.0], [15, -9.0, -63.0], [16, 0.0, -63.0], [17, 9.0, -63.0], [18, 18.0, -63.0], [19, 27.0, -63.0], [20, 36.0, -63.0], [21, 45.0, -63.0], [22, -54.0, -54.0], [23, -45.0, -54.0], [24, -36.0, -54.0], [25, -27.0, -54.0], [26, -18.0, -54.0], [27, -9.0, -54.0], [28, 0.0, -54.0], [29, 9.0, -54.0], [30, 18.0, -54.0], [31, 27.0, -54.0], [32, 36.0, -54.0], [33, 45.0, -54.0], [34, 54.0, -54.0], [35, -72.0, -45.0], [36, -63.0, -45.0], [37, -54.0, -45.0], [38, -45.0, -45.0], [39, -36.0, -45.0], [40, -27.0, -45.0], [41, -18.0, -45.0], [42, -9.0, -45.0], [43, 0.0, -45.0], [44, 9.0, -45.0], [45, 18.0, -45.0], [46, 27.0, -45.0], [47, 36.0, -45.0], [48, 45.0, -45.0], [49, 54.0, -45.0], [50, 63.0, -45.0], [51, 72.0, -45.0], [52, -72.0, -36.0], [53, -63.0, -36.0], [54, -54.0, -36.0], [55, -45.0, -36.0], [56, -36.0, -36.0], [57, -27.0, -36.0], [58, -18.0, -36.0], [59, 18.0, -36.0], [60, 27.0, -36.0], [61, 36.0, -36.0], [62, 45.0, -36.0], [63, 54.0, -36.0], [64, 63.0, -36.0], [65, 72.0, -36.0], [66, -72.0, -27.0], [67, -63.0, -27.0], [68, -54.0, -27.0], [69, -45.0, -27.0], [70, -36.0, -27.0], [71, -27.0, -27.0], [72, 27.0, -27.0], [73, 36.0, -27.0], [74, 45.0, -27.0], [75, 54.0, -27.0], [76, 63.0, -27.0], [77, 72.0, -27.0], [78, -72.0, -18.0], [79, -63.0, -18.0], [80, -54.0, -18.0], [81, -45.0, -18.0], [82, -36.0, -18.0], [83, 36.0, -18.0], [84, 45.0, -18.0], [85, 54.0, -18.0], [86, 63.0, -18.0], [87, 72.0, -18.0], [88, -72.0, -9.0], [89, -63.0, -9.0], [90, -54.0, -9.0], [91, -45.0, -9.0], [92, 45.0, -9.0], [93, 54.0, -9.0], [94, 63.0, -9.0], [95, 72.0, -9.0], [96, -72.0, 0.0], [97, -63.0, 0.0], [98, -54.0, 0.0], [99, -45.0, 0.0], [100, 45.0, 0.0], [101, 54.0, 0.0], [102, 63.0, 0.0], [103, 72.0, 0.0], [104, -72.0, 9.0], [105, -63.0, 9.0], [106, -54.0, 9.0], [107, -45.0, 9.0], [108, 45.0, 9.0], [109, 54.0, 9.0], [110, 63.0, 9.0], [111, 72.0, 9.0], [112, -72.0, 18.0], [113, -63.0, 18.0], [114, -54.0, 18.0], [115, -45.0, 18.0], [116, -36.0, 18.0], [117, 36.0, 18.0], [118, 45.0, 18.0], [119, 54.0, 18.0], [120, 63.0, 18.0], [121, 72.0, 18.0], [122, -72.0, 27.0], [123, -63.0, 27.0], [124, -54.0, 27.0], [125, -45.0, 27.0], [126, -36.0, 27.0], [127, -27.0, 27.0], [128, 27.0, 27.0], [129, 36.0, 27.0], [130, 45.0, 27.0], [131, 54.0, 27.0], [132, 63.0, 27.0], [133, 72.0, 27.0], [134, -72.0, 36.0], [135, -63.0, 36.0], [136, -54.0, 36.0], [137, -45.0, 36.0], [138, -36.0, 36.0], [139, -27.0, 36.0], [140, -18.0, 36.0], [141, 18.0, 36.0], [142, 27.0, 36.0], [143, 36.0, 36.0], [144, 45.0, 36.0], [145, 54.0, 36.0], [146, 63.0, 36.0], [147, 72.0, 36.0], [148, -72.0, 45.0], [149, -63.0, 45.0], [150, -54.0, 45.0], [151, -45.0, 45.0], [152, -36.0, 45.0], [153, -27.0, 45.0], [154, -18.0, 45.0], [155, -9.0, 45.0], [156, 0.0, 45.0], [157, 9.0, 45.0], [158, 18.0, 45.0], [159, 27.0, 45.0], [160, 36.0, 45.0], [161, 45.0, 45.0], [162, 54.0, 45.0], [163, 63.0, 45.0], [164, 72.0, 45.0], [165, -54.0, 54.0], [166, -45.0, 54.0], [167, -36.0, 54.0], [168, -27.0, 54.0], [169, -18.0, 54.0], [170, -9.0, 54.0], [171, 0.0, 54.0], [172, 9.0, 54.0], [173, 18.0, 54.0], [174, 27.0, 54.0], [175, 36.0, 54.0], [176, 45.0, 54.0], [177, 54.0, 54.0], [178, -45.0, 63.0], [179, -36.0, 63.0], [180, -27.0, 63.0], [181, -18.0, 63.0], [182, -9.0, 63.0], [183, 0.0, 63.0], [184, 9.0, 63.0], [185, 18.0, 63.0], [186, 27.0, 63.0], [187, 36.0, 63.0], [188, 45.0, 63.0], [189, -27.0, 72.0], [190, -18.0, 72.0], [191, -9.0, 72.0], [192, 0.0, 72.0], [193, 9.0, 72.0], [194, 18.0, 72.0], [195, 27.0, 72.0], [196, -9.0, 81.0], [197, 0.0, 81.0], [198, 9.0, 81.0], [199, 0.0, 90.0]]            # (id, x, y) mm: OFF-state loop cells outside the keep-out of radius 38.0 mm
WX = 160.6; WY = 196.6

oProject = oDesktop.NewProject()
oProject.InsertDesign("HFSS", "phase28_launcher", "DrivenModal", "")
oDesign = oProject.SetActiveDesign("phase28_launcher")
oEditor = oDesign.SetActiveEditor("3D Modeler")
import sys
def note(level, text):
    # print-only, never raises: a failed message must not stop the script
    try:
        oDesktop.AddMessage(oProject.GetName(), oDesign.GetName(), level, text)
    except Exception:
        pass
    try:
        sys.stdout.write(str(text) + "\n")
    except Exception:
        pass
oEditor.SetModelUnits(["NAME:Units Parameter", "Units:=", "mm", "Rescale:=", False])
oProject.GetDefinitionManager().AddMaterial(["NAME:HMSA_substrate", "CoordinateSystemType:=", "Cartesian",
    "BulkOrSurfaceType:=", 1, ["NAME:PhysicsTypes", "set:=", ["Electromagnetic"]],
    "permittivity:=", "2.2", "dielectric_loss_tangent:=", "0.0009"])
def var(name, value):
    oDesign.ChangeProperty(["NAME:AllTabs", ["NAME:LocalVariableTab", ["NAME:PropServers", "LocalVariables"],
        ["NAME:NewProps", ["NAME:" + name, "PropType:=", "VariableProp", "UserDef:=", True, "Value:=", value]]]])
for n, v in (("r_pin", mm(PIN_R)), ("r_out", "2.05mm"), ("pad_xy", "15mm"), ("pad_top", "30mm"), ("pad_bot", "15mm")):
    var(n, v)
Z = mm(H)
x_lo = "(-" + mm(WX / 2) + ")"; y_lo = "(-" + mm(WY / 2) + ")"
oEditor.CreateBox(["NAME:BoxParameters", "XPosition:=", x_lo, "YPosition:=", y_lo, "ZPosition:=", "0mm",
    "XSize:=", mm(WX), "YSize:=", mm(WY), "ZSize:=", Z], attrs("Substrate", "HMSA_substrate", True, "(0 128 0)", 0.6))
oEditor.CreateRectangle(["NAME:RectangleParameters", "IsCovered:=", True, "XStart:=", x_lo, "YStart:=", y_lo, "ZStart:=", "0mm",
    "Width:=", mm(WX), "Height:=", mm(WY), "WhichAxis:=", "Z"], attrs("Ground", "vacuum", True, "(128 128 128)"))
oBnd = oDesign.GetModule("BoundarySetup")
# pins: the driven pin at the origin (coax lumped port as in the Phase 26 script) and three grounded posts
PINS = [("Monopole1", 0.0, H + TD), ("Refl", -S_REFL, H + T_REFL), ("Dir1", S_D1, H + T_D1), ("Dir2", S_D1 + S_D2, H + T_D2)]
for nm, px, top in PINS:
    oEditor.CreateCylinder(["NAME:CylinderParameters", "XCenter:=", mm(px), "YCenter:=", "0mm", "ZCenter:=", "0mm",
        "Radius:=", "r_pin", "Height:=", mm(top), "WhichAxis:=", "Z", "NumSides:=", "0"], attrs(nm, "pec", False, "(255 255 0)"))
def circle(name, x, y, z, r, color="(255 128 0)"):
    oEditor.CreateCircle(["NAME:CircleParameters", "IsCovered:=", True, "XCenter:=", x, "YCenter:=", y, "ZCenter:=", z,
        "Radius:=", r, "WhichAxis:=", "Z", "NumSegments:=", "0"], attrs(name, "vacuum", True, color))
def subtract(blank, tools, keep):
    oEditor.Subtract(["NAME:Selections", "Blank Parts:=", blank, "Tool Parts:=", ",".join(tools)],
                     ["NAME:SubtractParameters", "KeepOriginals:=", keep])
circle("Hole1", "0mm", "0mm", "0mm", "r_out")
circle("PortSheet1", "0mm", "0mm", "0mm", "r_out")
circle("PinCut1", "0mm", "0mm", "0mm", "r_pin")
subtract("PortSheet1", ["PinCut1"], False)
subtract("Ground", ["Hole1"], False)
subtract("Substrate", [p[0] for p in PINS], True)
oBnd.AssignLumpedPort(["NAME:Port1", "Objects:=", ["PortSheet1"], "DoDeembed:=", False, "RenormalizeAllTerminals:=", True,
    ["NAME:Modes", ["NAME:Mode1", "ModeNum:=", 1, "UseIntLine:=", True,
        ["NAME:IntLine", "Start:=", ["r_pin", "0mm", "0mm"], "End:=", ["r_out", "0mm", "0mm"]],
        "AlignmentGroup:=", 0, "CharImp:=", "Zpi", "RenormImp:=", "50ohm"]],
    "ShowReporterFilter:=", False, "ReporterFilter:=", [True], "Impedance:=", "50ohm"])
oBnd.AssignPerfectE(["NAME:PerfE_Ground", "Objects:=", ["Ground"], "InfGroundPlane:=", False])
# OFF-state loop cells: five metal pieces + one diode sheet (C only) per cell, zero-thickness metal at the substrate surface
if LOADED_SURFACE:
    h = SO / 2.0
    def rect_pts(cx, cy, x0, x1, y0, y1):
        return [(cx + x0, cy + y0), (cx + x1, cy + y0), (cx + x1, cy + y1), (cx + x0, cy + y1)]
    names = []
    for cid, cx, cy in CELLS:
        for nm, (x0, x1, y0, y1) in (("b", (-h, h, -h, -h + WR)), ("l", (-h, -h + WR, -h + WR, h - WR)), ("r", (h - WR, h, -h + WR, h - WR)),
                                     ("tl", (-h, -GAP / 2.0, h - WR, h)), ("tr", (GAP / 2.0, h, h - WR, h))):
            poly_sheet(oEditor, "M%d_%s" % (cid, nm), rect_pts(cx, cy, x0, x1, y0, y1), Z)
            names.append("M%d_%s" % (cid, nm))
    blocks = []
    for b in range(0, len(names), 100):
        grp = names[b:b + 100]
        if len(grp) > 1:
            oEditor.Unite(["NAME:Selections", "Selections:=", ",".join(grp)], ["NAME:UniteParameters", "KeepOriginals:=", False])
        blocks.append(grp[0])
    if len(blocks) > 1:
        oEditor.Unite(["NAME:Selections", "Selections:=", ",".join(blocks)], ["NAME:UniteParameters", "KeepOriginals:=", False])
    oEditor.ChangeProperty(["NAME:AllTabs", ["NAME:Geometry3DAttributeTab", ["NAME:PropServers", names[0]],
        ["NAME:ChangedProps", ["NAME:Name", "Value:=", "Metal"]]]])
    oBnd.AssignPerfectE(["NAME:PerfE_Metal", "Objects:=", ["Metal"], "InfGroundPlane:=", False])
    failed = []
    for cid, cx, cy in CELLS:
        nm = "D%d" % cid
        poly_sheet(oEditor, nm, rect_pts(cx, cy, -GAP / 2.0, GAP / 2.0, h - WR, h), Z, "(255 0 0)")
        try:
            oBnd.AssignLumpedRLC(["NAME:" + nm + "_RLC", "Objects:=", [nm],
                ["NAME:CurrentLine", "Start:=", [mm(cx - GAP / 2.0), mm(cy + h - WR / 2.0), Z], "End:=", [mm(cx + GAP / 2.0), mm(cy + h - WR / 2.0), Z]],
                "RLC Type:=", "Parallel", "UseResist:=", False, "Resistance:=", "0ohm", "UseInduct:=", False, "Inductance:=", "0nH",
                "UseCap:=", True, "Capacitance:=", C_OFF])
        except Exception as e:
            failed.append(nm)
    if failed:
        note(2, "Lumped RLC assignment failed for %d sheets (first %s): assign C = 0.0282 pF by hand." % (len(failed), failed[0]))
# non-model polyline: the surface-wave field on a circle of radius R_FIELD at 1 mm above the surface (export Ez / |E| versus the azimuth)
R_FIELD = 60.0
pts = [[mm(R_FIELD * math.cos(math.radians(a))), mm(R_FIELD * math.sin(math.radians(a))), mm(H + 1.0)] for a in range(-180, 181, 5)]
try:
    oEditor.CreatePolyline(["NAME:PolylineParameters", "IsPolylineCovered:=", False, "IsPolylineClosed:=", False,
        ["NAME:PolylinePoints"] + [["NAME:PLPoint", "X:=", p[0], "Y:=", p[1], "Z:=", p[2]] for p in pts],
        ["NAME:PolylineSegments"] + [["NAME:PLSegment", "SegmentType:=", "Line", "StartIndex:=", k, "NoOfPoints:=", 2] for k in range(len(pts) - 1)],
        ["NAME:PolylineXSection", "XSectionType:=", "None", "XSectionOrient:=", "Auto", "XSectionWidth:=", "0mm",
         "XSectionTopWidth:=", "0mm", "XSectionHeight:=", "0mm", "XSectionNumSegments:=", "0", "XSectionBendType:=", "Corner"]],
        attrs("AzimuthCircle60", "vacuum", False, "(0 0 255)"))
except Exception as e:
    note(1, "Azimuth polyline not created (%s): create a circle R = 60 mm, z = H + 1 mm by hand." % str(e))
oEditor.CreateBox(["NAME:BoxParameters", "XPosition:=", x_lo + "-pad_xy", "YPosition:=", y_lo + "-pad_xy", "ZPosition:=", "-pad_bot",
    "XSize:=", mm(WX) + "+2*pad_xy", "YSize:=", mm(WY) + "+2*pad_xy", "ZSize:=", "pad_bot+" + Z + "+pad_top"],
    attrs("Air", "air", True, "(143 175 143)", 0.9))
oBnd.AssignRadiation(["NAME:Rad1", "Objects:=", ["Air"], "IsFssReference:=", False, "IsForPML:=", False])
oAna = oDesign.GetModule("AnalysisSetup")
oAna.InsertSetup("HfssDriven", ["NAME:Setup1", "Frequency:=", "10GHz", "MaxDeltaS:=", 0.02, "MaximumPasses:=", 15, "MinimumPasses:=", 2,
    "MinimumConvergedPasses:=", 2, "PercentRefinement:=", 30, "IsEnabled:=", True, "BasisOrder:=", 1, "DoLambdaRefine:=", True,
    "DoMaterialLambda:=", True, "SetLambdaTarget:=", False, "Target:=", 0.3333, "UseMaxTetIncrease:=", False])
oAna.InsertFrequencySweep("Setup1", ["NAME:Sweep", "IsEnabled:=", True, "RangeType:=", "LinearStep", "RangeStart:=", "9.5GHz", "RangeEnd:=", "10.5GHz",
    "RangeStep:=", "0.05GHz", "Type:=", "Interpolating", "SaveFields:=", False, "SaveRadFields:=", False,
    "InterpTolerance:=", 0.5, "InterpMaxSolns:=", 250, "InterpMinSolns:=", 0, "InterpMinSubranges:=", 1])
oEditor.FitAll()
oProject.SaveAs(oDesktop.GetProjectDirectory() + "/phase28_launcher.aedt", True)
note(0, "Built: driven pin + 3 posts, %d OFF-state loop cells (LOADED_SURFACE=%s). Validate, Analyze; export S11 and the field on AzimuthCircle60." % (len(CELLS) if LOADED_SURFACE else 0, LOADED_SURFACE))
